/* FONT
======================================*/
/* 1 - MENU CONTAINER
======================================*/
.defaultmainmenu,
.defaultmainmenu *{
	font-family: inherit;
	box-sizing:border-box;
	-moz-box-sizing:border-box; 
	-webkit-box-sizing:border-box;
}
.defaultmainmenu{
	/* width: 100%; */
	padding: 0 30px;
	/* float: left; */
	/* position: relative; */
	background: #fff;
}
.defaultmainmenu a{
	-o-transition: color .3s linear, background .3s linear;
	-moz-transition: color .3s linear, background .3s linear;
	-webkit-transition: color .3s linear, background .3s linear;
	transition: color .3s linear, background .3s linear;
}
/* scrollable menu */
.defaultmainmenu-menu.scrollable > .scrollable-fix{
	display: none;
}

/* 2 - BRAND
======================================*/
.defaultmainmenu-brand{
	margin: 18px 30px 0 0;
	float: left;
	color: #666;
	text-decoration: none;
	font-size: 24px;
	font-weight: 600;
	line-height: 1.3;
	cursor: pointer;
}

/* 3 - MENU
======================================*/
.defaultmainmenu-menu{
	margin: 0;
	padding: 0;
	float: left;
	list-style: none;
}
/* Right alignment */
.defaultmainmenu-menu.defaultmainmenu-right{
	float: right;
}
/* Menu items */
.defaultmainmenu-menu > li{
	display: inline-block;
	float: left;
}
.defaultmainmenu-menu > li > a{
	padding: 26px 16px;
	display: inline-block;
	text-decoration: none;
	font-size: 14px;
	font-weight: 600;
	color: #888;
	outline: 0;
	line-height: 1.42857143;
	-webkit-tap-highlight-color: rgba(0,0,0,0);
	-webkit-tap-highlight-color: transparent;
}
/* Active/hover state (Menu items) */
.defaultmainmenu-menu > li.active > a,
.defaultmainmenu-menu > li:hover > a{
	color: #fff;
}

/* 4 - DROPDOWN
======================================*/
.defaultmainmenu-menu ul.dropdown,
.defaultmainmenu-menu ul.dropdown li ul.dropdown{
	list-style: none;
    margin: 0;
    padding: 0;   
	display: none;
    position: absolute;
    z-index: 99;
	min-width: 180px;
	background: #fff;
}
.defaultmainmenu-menu ul.dropdown li ul.dropdown{
    left: 100%;
}
/* Dropdown items */
.defaultmainmenu-menu ul.dropdown li{
	clear: both;
	width: 100%;
	border: 0 none;
	font-size: 12px;
	position: relative;
}
.defaultmainmenu-menu ul.dropdown li a{
	width: 100%;
	background: none;
	padding: 10px 25px 10px 22px;
	color: #888;
	text-decoration: none;
	display: inline-block;
	float: left;
	clear: both;
	position: relative;
	outline: 0;
	-o-transition:all .2s linear;
	-moz-transition:all .2s linear;
	-webkit-transition:all .2s linear;
	transition:all .2s linear;
}
/* Hover state (dropdown items) */
.defaultmainmenu-menu ul.dropdown li:hover > a{
	padding-left: 28px;
	padding-right: 19px;
	color: #333;
}

/* Dropdown left alignment */
.defaultmainmenu-menu ul.dropdown.dropdown-left{
	left: none;
}
.defaultmainmenu-menu ul.dropdown li ul.dropdown.dropdown-left{
	left: -100%;
}

/* 5 - DROPDOWN/MEGAMENU INDICATORS
======================================*/
.defaultmainmenu-menu li .indicator{
	margin-left: 9px;
	font-family: 'FontAwesome';
}
.defaultmainmenu-menu li ul.dropdown li .indicator{
	position: absolute;
	top: 8px;
	right: 10px;
	font-size: 15px;
}

/* 6 - MEGAMENU
======================================*/
.defaultmainmenu-menu > li > .megamenu{
	width: 100%;
	padding: 20px 30px;
	left: 0;
	position: absolute;
	display: none;
	z-index: 99;
	border-top: solid 1px #f0f0f0;
	background: #fff;
}

/* 7 - MEGAMENU WIDTHS
======================================*/
/* Half width */
.defaultmainmenu-menu > li > .megamenu.megamenu-half-width{
	width: 50%;
	left: auto;
}
/* Quarter width */
.defaultmainmenu-menu > li > .megamenu.megamenu-quarter-width{
	width: 25%;
	left: auto;
}

/* 8 - GRID SYSTEM
======================================*/
.defaultmainmenu-menu > li > .megamenu .megamenu-row{
	width: 100%;
	margin-top: 15px;
}
.defaultmainmenu-menu > li > .megamenu .megamenu-row:first-child {
	margin-top: 0;
}
.defaultmainmenu-menu > li > .megamenu .megamenu-row:before,
.defaultmainmenu-menu > li > .megamenu .megamenu-row:after {
