*/

@font-face {
    font-family: 'Roboto-light';
    src: url('../fonts/Roboto-Light.ttf');
    font-weight: 300;
}


/* ==============================
   2. Global styles
   ============================== */

body {
    font-family: 'Roboto', sans-serif;
    color: #999;
}

h1,
h2,
h3,
h4,
h5,
h6,
p,
ul {
    margin: 0;
    padding: 0;
}

h1,
h2,
h3,
h4,
h5 {
    font-family: 'Roboto Slab', serif;
    color: #303030;
}

ul {
    padding: 0;
}

ul li {
    font-size: 16px;
    color: #333333;
    line-height: 22px;
    list-style: disc;
}

p {
    font-size: 15px;
    color: #3e4e4a;
    line-height: 26px;
    margin-bottom: 15px;
}

a {
    text-decoration: none;
    display: inline-block;
    outline: none;
    color: #006b4f;
}

a:hover,
a:focus {
    text-decoration: none;
    outline: none;
    color: #12b88c;
}

.extr-mrg {
    margin: 50px 0 !important;
}

.extr-mrg-btm {
    margin-bottom: 40px !important;
}

.extr-mrg-top {
    margin-top: 40px !important;
}

.text-center.extr-mrg-btm {
    max-width: 920px;
    margin: 0 auto;
}

button {
    border: none;
    outline: none;
    box-shadow: none;
    display: block;
    padding: 0;
    margin: 7px;
    background: transparent;
}

.defaultmainmenu-menu ul.dropdown li {
    list-style: none;
}

input,
textarea {
    font-family: 'Roboto', sans-serif;
    display: block;
    font-size: 16px;
    line-height: 28px;
    outline: none;
    box-shadow: none;
    -webkit-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
}

.width-100 {
    width: 100%;
}

.boxed_wrapper {
    width: 100%;
    background: #fff;
    overflow-x: hidden;
}

.sec-padd {
    padding: 60px 0;
}

.sec-padd2 {
    padding: 60px 0 30px;
}

.sec-padd3 {
    padding: 60px 0 50px;
}


