}

.sec-padd-bottom {
    padding-bottom: 80px;
}

.no-padd {
    padding: 0px;
}

.paddt-50 {
    padding-top: 50px;
}

.overlay3 {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    top: 0;
    left: 0;
    width: 100%;
    height: 0%;
    opacity: 0;
    visibility: hidden;
    background: rgba(0, 0, 0, 0.9);
    -webkit-transition: .7s ease;
    -moz-transition: .7s ease;
    -ms-transition: .7s ease;
    -o-transition: .7s ease;
    transition: .7s ease;
}

.inner-box {
    position: relative;
}

.list_inline li {
    display: inline-block;
}

.padd-80 {
    padding-top: 80px;
}

.tran3s {
    -webkit-transition: all 0.3s ease-in-out;
