}

.center {
    text-align: center;
}

.thm-color {
    color: #b82b00;
}

.scroll-down {
    background: #b82b00;
    height: 70px;
    width: 70px;
    color: #fff;
    font-size: 54px;
    font-weight: bold;
    border-radius: 50%;
    text-align: center;
    line-height: 70px;
    position: absolute;
    bottom: -45px;
    left: 50%;
    transform: translate(-50%, 0);
    transition: all 0.5s ease-in-out;
}

.scroll-down:hover,
.scroll-down:focus {
    background: #ff5722;
    color: #fff;
}

