.about-video {
    -ms-flex-preferred-size: calc(100% * (4/12));
    flex-basis: calc(100% * (4/12));
    background: url(../assets/images/video-thumb.jpg) no-repeat center center /cover;
    border-radius: 5px;
    box-shadow: 0px 0px 8px rgba(0, 0, 0, 0.4);
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    position: relative;
    z-index: 1;
}
.introduction-wrap .about-video {
    -ms-flex-preferred-size: calc(100% * (7/12));
    flex-basis: calc(100% * (7/12));
    background: url(../assets/images/video-thumb.jpg) no-repeat center center /cover;
}

.about-video:before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    height: 100%;
    width: 100%;
    z-index: -1;
    background: rgba(0, 20, 15, 0.68);
}

.about-video a {
    margin: auto;
    display: block;
    border-radius: 50%;
    position: relative;
}

.about-video a img {
    height: 60px;
}

.about-video a:before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    height: 100%;
    width: 100%;
    border-radius: 50%;
    border: 2px solid #ffffff;
    -webkit-animation: scaling 2000ms linear 0s infinite;
    animation: scaling 2000ms linear 0s infinite;
}

.about-video a:after {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    height: 100%;
    width: 100%;
    border-radius: 50%;
    border: 1px solid #ffffff;
    -webkit-animation: scaling 2000ms linear 1s infinite;
    animation: scaling 2000ms linear 1s infinite;
}

